package com.chance.bitlifediag;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.Toast;
import java.io.*;import java.util.*;import java.util.zip.*;
/** User-selected destination; no storage permission and no network upload. */
public final class DiagnosticsExport54 extends Activity {
 public static void open(Activity a){a.startActivity(new Intent(a,DiagnosticsExport54.class));}
 protected void onCreate(Bundle state){super.onCreate(state);RuntimeLogCapture.install(this);if(state==null){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/zip");intent.putExtra(Intent.EXTRA_TITLE,"MayoMods_1108_diagnostics.zip");startActivityForResult(intent,54);}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=54)return;if(result!=RESULT_OK||data==null||data.getData()==null){finish();return;}final Uri destination=data.getData();new Thread(new Runnable(){public void run(){String message;try{File root=RuntimeLogCapture.diagnosticRoot();if(root==null)throw new IOException("No diagnostic session");try(OutputStream output=getContentResolver().openOutputStream(destination);ZipOutputStream zip=new ZipOutputStream(output)){Set<String> seen=new HashSet<String>();addTree(zip,root,"diagnostics/",seen,0);File external=getExternalFilesDir(null);if(external!=null){File[] nativeFiles=external.listFiles();if(nativeFiles!=null)for(File file:nativeFiles)if(file.isFile()&&file.getName().startsWith("tombstone"))add(zip,file,"unity/"+file.getName(),seen);}File[] extra=getFilesDir().listFiles();if(extra!=null)for(File file:extra)if(file.isFile()&&file.getName().startsWith("tombstone_"))add(zip,file,"android/"+file.getName(),seen);zip.putNextEntry(new ZipEntry("summary.txt"));zip.write(RuntimeLogCapture.report(false).getBytes("UTF-8"));zip.closeEntry();try(InputStream in=getAssets().open("mayomods54/native_symbols.json")){zip.putNextEntry(new ZipEntry("native_symbols.json"));copy(in,zip,8*1024*1024);zip.closeEntry();}}message="Diagnostic ZIP saved";}catch(Exception error){RuntimeLogCapture.failure("Exporting diagnostics",error);message="Export failed: "+error.getMessage();}final String text=message;runOnUiThread(new Runnable(){public void run(){Toast.makeText(DiagnosticsExport54.this,text,1).show();finish();}});}},"MayoModsExport").start();}
 private static void addTree(ZipOutputStream zip,File folder,String prefix,Set<String> seen,int depth)throws IOException{if(depth>3)return;File[] files=folder.listFiles();if(files==null)return;Arrays.sort(files);for(File file:files){if(file.getName().endsWith(".pending"))continue;if(file.isDirectory())addTree(zip,file,prefix+file.getName()+"/",seen,depth+1);else add(zip,file,prefix+file.getName(),seen);}}
 private static void add(ZipOutputStream zip,File file,String name,Set<String> seen)throws IOException{if(!seen.add(name))return;if(file.length()>16L*1024*1024)return;zip.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(file)){copy(in,zip,16*1024*1024);}zip.closeEntry();}
 private static void copy(InputStream in,OutputStream out,int limit)throws IOException{byte[] buffer=new byte[8192];int n,total=0;while((n=in.read(buffer))!=-1){total+=n;if(total>limit)throw new IOException("Diagnostic file exceeds export bound");out.write(buffer,0,n);}}
}
